package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Hidden F2P regression test (ADR-0032.1 S4). With no header routes, the
// RouteHeaders middleware must call the next handler exactly once.
func TestGHXRouteHeadersEmptyCallsNextOnce(t *testing.T) {
	var calls int
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { calls++ })
	h := RouteHeaders().Handler(next)
	req := httptest.NewRequest("GET", "/", nil)
	h.ServeHTTP(httptest.NewRecorder(), req)
	if calls != 1 {
		t.Fatalf("next handler called %d times, want 1 (missing return double-calls)", calls)
	}
}
GHXEOF
